rows[57933]={title={{19,387433701},"속임수 거래"},description={"^the current party or raid member becomes the target of your tricks of the trade%. the threat caused by your next attack and all actions taken for ([%+%-]?%d[%d,.]* %a+) afterwards will be transferred to the target%. in addition, all damage caused by the target is increased by ([%+%-]?%d[%d,.%+%-to –]*)%% during this time%.$","현재 파티원 혹은 공격대원이 속임수 거래의 대상이 되어 \0311\031 동안 자신의 모든 공격과 행동으로 발생한 위협 수준이 대상에게 전이됩니다. 추가로 이 동안에는 대상의 모든 공격력이 \0312\031%만큼 증가합니다.",{1,0},{1,2}},aura={"^all damage caused increased by ([%+%-]?%d[%d,.%+%-to –]*)%%%. all threat transferred from the rogue to the target%.$","모든 공격력 \0311\031%만큼 증가\010도적의 위협 수준 모두 이전됨",{0},{1}}}
rows[57934]={title={{19,387433701},"속임수 거래"},aura={"^the threat caused by your next damaging attack and all actions taken for ([%+%-]?%d[%d,.]* %a+) afterwards will be transferred to the target%. in addition, all damage caused by the target is increased during this time%.$","피해를 입히는 다음 공격과 이후 \0311\031 동안 취하는 모든 행동으로 발생하는 위협 수준을 대상 파티원 혹은 공격대원에게 이전\010대상의 모든 공격력 증가",{1},{1}}}
