rows[60069]={title={{10,40502760},"분산"},description={"^you disperse into pure shadow energy, reducing all damage taken by ([%+%-]?%d[%d,.%+%-to –]*)%%%. you are unable to attack or cast spells, but you regenerate ([%+%-]?%d[%d,.%+%-to –]*)%% mana every ([%+%-]?%d[%d,.%+%-to –]*) sec for ([%+%-]?%d[%d,.]* %a+)%. dispersion can be cast while stunned, feared or silenced%. clears all snare and movement impairing effects when cast, and makes you immune to them while dispersed%.$","순수한 암흑의 에너지로 흩어져, 받는 모든 피해를 \0311\031%만큼 감소시킵니다. 이 동안에는 공격하거나 주문을 시전할 수 없지만, \0314\031에 걸쳐 \0313\031초마다 \0312\031%의 마나를 회복합니다.\010\010기절, 공포, 침묵 상태 중에도 시전할 수 있습니다. 모든 이동 방해 효과와 감속 효과를 제거하며, 분산 효과가 지속되는 동안에는 해당 효과에 면역이 됩니다.",{0,0,0,1},{1,2,3,4}},aura={"^reduces all damage by and you regenerate ([%+%-]?%d[%d,.%+%-to –]*)%% mana every ([%+%-]?%d[%d,.%+%-to –]*) sec for ([%+%-]?%d[%d,.]* %a+)%. cannot attack or cast spells%.$","\0313\031 동안 받는 모든 피해 감소 및 \0312\031초마다 \0311\031%의 마나 회복\010공격 및 주문 시전 불가",{0,0,1},{1,2,3}}}
