rows[61088]={title={{12,547135106},"좀비 떼"},description={"^summons an entire horde of zombies to fight for the death knight%. the zombies will swarm the area, fighting anything they can%. while channelling zombie horde, the death knight takes ([%+%-]?%d[%d,.%+%-to –]*)%% less damage%.$","좀비의 떼를 소환하여 죽음의 기사를 도와 싸우게 합니다. 좀비는 떼를 이루어 적과 맞서 싸웁니다. 정신을 집중하는 동안 죽음의 기사는 받는 피해가 \0311\031%만큼 감소합니다.",{0},{1}},aura={"^summoning zombies%. damage reduced by ([%+%-]?%d[%d,.%+%-to –]*)%%%.$","좀비 소환\010받는 피해 \0311\031%만큼 감소",{0},{1}}}
