rows[62380]={title={{26,986871509},"하급 저항의 영약"},description={"^increases your resistance to all schools of magic by ([%+%-]?%d[%d,.%+%-to –]*) for ([%+%-]?%d[%d,.]* %a+)%. counts as both a battle and guardian elixir%. this effect persists through death%.$","\0312\031 동안 모든 마법에 대한 저항력이 \0311\031만큼 증가합니다. 동시에 전투 비약 및 강화 비약으로 간주됩니다. 이 효과는 죽어도 지속됩니다.",{0,1},{1,2}},aura={"^resistance to all schools of magic increased by ([%+%-]?%d[%d,.%+%-to –]*) for ([%+%-]?%d[%d,.]* %a+)%. counts as both a battle and guardian elixir%.$","\0312\031 동안 모든 마법에 대한 저항력 \0311\031만큼 증가\010전투 비약 및 강화 비약",{0,1},{1,2}}}
