rows[62382]={title={{7,1880512626},"부서지는 몸"},description={"^the cold water causes molten iron constructs to rapidly solidify, rendering them unable to act%. in addition, if they are dealt more than 5000 damage during this state, they will shatter, dealing ([%+%-]?%d[%d,.%+%-to –]*) damage to all enemies in a ([%+%-]?%d[%d,.%+%-to –]*) yard radius%.$","차가운 물이 녹아내리는 무쇠 피조물을 응고시켜 움직이지 못하게 만듭니다. 추가로, 이 상태에서 5000 이상의 피해를 받게 되면 부서지면서 \0312\031미터 반경 내에 있는 모든 적에게 \0311\031의 피해를 입힙니다.",{0,0},{1,2}},aura={"^stunned%. chance to receive critical hits increased by ([%+%-]?%d[%d,.%+%-to –]*)%%%. shatters if dealt 5000 damage or more in a single attack%.$","기절함\010치명타 공격에 적중 당할 확률 \0311\031%만큼 증가\010한 번 공격으로 5000 이상의 피해를 받으면 부서짐",{0},{1}}}
rows[62383]={title={{7,274375905},"산산조각"},description={"^deals ([%+%-]?%d[%d,.%+%-to –]*) physical damage to all enemies within ([%+%-]?%d[%d,.%+%-to –]*) yards%. damage from this effect ignores armor%.$","\0311\031미터 반경 내에 있는 모든 적에게 \0311\031의 물리 피해를 입힙니다. 이 효과로 인한 피해는 방어도를 무시합니다.",{0,0},{1,1}}}
