rows[62659]={title={{12,478631922},"어둠 붕괴"},description={"^fires a shadow missile at a target, dealing ([%+%-]?%d[%d,.%+%-to –]*) shadow damage to all enemies near the impact point and knocking them away%. after impact, leaves an energy field that lingers for ([%+%-]?%d[%d,.]* %a+), increasing damage dealt by ([%+%-]?%d[%d,.%+%-to –]*)%%, reducing healing done by ([%+%-]?%d[%d,.%+%-to –]*)%%, and reducing mana costs by ([%+%-]?%d[%d,.%+%-to –]*)%%%.$","대상에게 어둠의 화살을 발사하여 충돌 지점 주변의 모든 적에게 \0311\031의 암흑 피해를 입히고 뒤로 밀쳐냅니다. 충격이 사라지면 \0312\031 동안 에너지장이 형성되고 공격력이 \0313\031%만큼 증가하며 치유 효과가 \0314\031%만큼, 주문에 소비되는 마나가 \0315\031%만큼 감소합니다.",{0,1,0,0,0},{1,2,3,4,5}}}
rows[62660]={title={{12,478631922},"어둠 붕괴"},description={"^fires a missile towards a random target%. when this missile lands, it deals ([%+%-]?%d[%d,.%+%-to –]*) shadow damage to all enemies within ([%+%-]?%d[%d,.%+%-to –]*) yards of that location%.$","무작위 대상에게 화살을 발사하여 화살의 낙하 지점에서 \0312\031미터 반경 내에 있는 모든 적들에게 \0311\031의 암흑 피해를 입힙니다.",{0,0},{1,2}}}
rows[62661]={title={{14,2062047737},"이글거리는 불길"},description={"^deals ([%+%-]?%d[%d,.%+%-to –]*) fire damage to all enemies within ([%+%-]?%d[%d,.%+%-to –]*) yards, superheating their armor and reducing its ability to protect them by ([%+%-]?%d[%d,.%+%-to –]*)%% for ([%+%-]?%d[%d,.]* %a+)%.$","\0312\031미터 반경 내에 있는 모든 적에게 \0311\031의 화염 피해를 입히고 방어구를 뜨겁게 가열하여 \0314\031 동안 방어도를 \0313\031%만큼 감소시킵니다.",{0,0,0,1},{1,2,3,4}},aura={"^armor reduced by ([%+%-]?%d[%d,.%+%-to –]*)%%%.$","방어도 \0311\031%만큼 감소",{0},{1}}}
rows[62662]={title={{17,1096629967},"어둠의 쇄도"},description={"^empowers the caster with dark might, increasing physical damage by ([%+%-]?%d[%d,.%+%-to –]*)%% but reducing movement speed by ([%+%-]?%d[%d,.%+%-to –]*)%%, for ([%+%-]?%d[%d,.]* %a+)%.$","어둠의 힘을 시전자에게 불어넣습니다. \0313\031 동안 물리 공격력이 \0311\031%만큼 증가하지만 이동 속도가 \0312\031%만큼 감소합니다.",{0,0,1},{1,2,3}},aura={"^physical damage increased by ([%+%-]?%d[%d,.%+%-to –]*)%%%. movement speed reduced by ([%+%-]?%d[%d,.%+%-to –]*)%%%.$","물리 공격력 \0311\031%만큼 증가\010이동 속도 \0312\031%만큼 감소",{0,0},{1,2}}}
