rows[63239]={title={{11,1396332100},"가시 더미"},description={"^inflicts ([%+%-]?%d[%d,.%+%-to –]*) nature damage to enemies within ([%+%-]?%d[%d,.%+%-to –]*) yards of the target%.$","대상으로부터 \0312\031미터 반경 내에 있는 적들에게 \0311\031의 자연 피해를 입힙니다.",{0,0},{1,2}},aura={"^inflicts ([%+%-]?%d[%d,.%+%-to –]*) nature damage to enemies within ([%+%-]?%d[%d,.%+%-to –]*) yards of the target%.$","대상으로부터 \0312\031미터 반경 내에 있는 적들에게 \0311\031의 자연 피해",{0,0},{1,2}}}
