rows[63241]={title={{11,2094029573},"평온"},description={"^regenerates all nearby group members for ([%+%-]?%d[%d,.%+%-to –]*) every ([%+%-]?%d[%d,.%+%-to –]*) seconds for ([%+%-]?%d[%d,.]* %a+)%. channeled%.$","\0313\031 동안 \0312\031초마다 주위의 모든 파티원의 생명력을 \0311\031만큼 회복시킵니다. 정신 집중이 필요합니다.",{0,0,1},{1,2,3}},aura={"^heals nearby party members for ([%+%-]?%d[%d,.%+%-to –]*) every ([%+%-]?%d[%d,.%+%-to –]*) seconds%.$","\0312\031초마다 주위 파티원의 생명력을 \0311\031만큼 회복",{0,0},{1,2}}}
rows[63242]={title={{7,1212564781},"육성"},description={"^heals a friendly target for ([%+%-]?%d[%d,.%+%-to –]*)%. heals for an additional 20%% if you have a rejuvenation, regrowth, or lifebloom effect active on the target%.$","아군 대상의 생명력을 \0311\031만큼 회복시킵니다. 회복, 재생, 피어나는 생명 효과가 걸려 있는 대상은 회복되는 생명력이 20%만큼 증가합니다.",{0},{1}}}
rows[63247]={title={{14,1234965650},"살아있는 지진해일"},description={"^you summon a living tsunami that does ([%+%-]?%d[%d,.%+%-to –]*) nature damage when in contact with hostile targets, inflicting an additional ([%+%-]?%d[%d,.%+%-to –]*) nature damage every ([%+%-]?%d[%d,.%+%-to –]*) sec for ([%+%-]?%d[%d,.]* %a+)%.$","적대적인 대상에게 \0311\031의 자연 피해를 입히고 추가로 \0314\031 동안 \0313\031초마다 \0312\031의 추가 자연 피해를 입히는 살아있는 지진해일을 소환합니다.",{0,0,0,1},{1,2,3,4}},aura={"^inflicts ([%+%-]?%d[%d,.%+%-to –]*) nature damage every ([%+%-]?%d[%d,.%+%-to –]*) sec%.$","\0312\031초마다 \0311\031의 자연 피해",{0,0},{1,2}}}
