rows[63268]={title={{17,1981382024},"문양: 변장"},description={"^when you pick pocket a humanoid enemy, you also copy their appearance for ([%+%-]?%d[%d,.]* %a+)%. your disguise will unravel upon entering combat%.$","인간형 적에게 훔치기를 사용하면 \0311\031 동안 대상의 모습으로 변장합니다. 전투를 시작하면 정체가 탄로납니다.",{1},{1}}}
rows[63269]={title={{25,1510459078},"문양: 그림자 망토"},description={"^while cloak of shadows is active, you take ([%+%-]?%d[%d,.%+%-to –]*)%% less physical damage%.$","그림자 망토 효과가 활성화되어 있는 동안 받는 물리 피해가 \0311\031%만큼 감소합니다.",{0},{1}}}
