rows[63272]={title={{9,1979352659},"싹쓸바람"},description={"^creates a violent storm in the target area causing ([%+%-]?%d[%d,.%+%-to –]*) nature damage to enemies every ([%+%-]?%d[%d,.%+%-to –]*) sec, and increasing the time between the attacks of enemies by ([%+%-]?%d[%d,.%+%-to –]*)%%%. lasts ([%+%-]?%d[%d,.]* %a+)%. must channel to maintain the spell%.$","대상 지역에 맹렬한 폭풍을 생성하여 \0312\031초마다 적에게 \0311\031의 자연 피해를 입히고 적의 공격 간격을 \0313\031%만큼 늘입니다. \0314\031 동안 지속됩니다. 주문을 유지하려면 계속 정신을 집중해야 합니다.",{0,0,0,1},{1,2,3,4}},aura={"^([%+%-]?%d[%d,.%+%-to –]*) nature damage every ([%+%-]?%d[%d,.%+%-to –]*) seconds, and slow attacks and spells by ([%+%-]?%d[%d,.%+%-to –]*)%%%.$","\0312\031초마다 \0311\031의 자연 피해\010공격 및 주문 시전 속도 \0313\031%만큼 저하",{0,0,0},{1,2,3}}}
rows[63273]={title={{16,1833705408},"문양: 성난 해일"},description={"^removes the cooldown of riptide, but reduces the initial direct healing by ([%+%-]?%d[%d,.%+%-to –]*)%%%.$","성난 해일 주문의 재사용 대기시간이 사라지지만 대상 아군에 대한 즉시 치유 효과가 \0311\031%만큼 감소합니다.",{0},{1}}}
rows[63274]={title={{19,628207211},"P3Wx2 레이저 탄막"},description={"^spins up the dual cannons for ([%+%-]?%d[%d,.]* %a+) before unleashing a spray of lasers in a random direction, dealing ([%+%-]?%d[%d,.%+%-to –]*) spellfire damage every ([%+%-]?%d[%d,.%+%-to –]*) sec to all enemies caught inside%. lasts ([%+%-]?%d[%d,.]* %a+)%.$","\0311\031 동안 이중 대포를 제자리에서 회전시키고, 무작위 방향으로 레이저포를 난사하여 걸려 드는 모든 적들에게 \0313\031초마다 \0312\031의 비전화염 피해를 입힙니다. \0314\031 동안 지속됩니다.",{1,0,0,1},{1,2,3,4}}}
rows[63275]={title={{7,421847164},"낚시"},description={{209,583822655},"낚싯대를 착용하고 물가에서 사용하면 낚시를 시작합니다. 찌가 흔들릴 때 오른쪽 클릭을 하여 물고기를 낚을 수 있습니다. 숙련도가 높으면 고레벨 지역에서 물고기를 낚을 확률이 높아집니다."}}
rows[63276]={title={{20,1039084707},"얼굴 없는 자의 징표"},description={"^inflicts an ancient malediction on a target, siphoning ([%+%-]?%d[%d,.%+%-to –]*) health every ([%+%-]?%d[%d,.%+%-to –]*) sec%. from enemies near the target, for ([%+%-]?%d[%d,.]* %a+)%.$","대상에게 고대의 저주를 내려 대상 주위의 적에게서 \0312\031초마다 \0311\031의 생명력을 흡수합니다. \0313\031 동안 지속됩니다.",{0,0,1},{1,2,3}},aura={"^siphoning ([%+%-]?%d[%d,.%+%-to –]*) health from nearby allies every ([%+%-]?%d[%d,.%+%-to –]*) sec%., healing general vezax%.$","주위 아군에게서 \0312\031초마다 \0311\031의 생명력 흡수\010장군 베작스에게 이전",{0,0},{1,2}}}
rows[63277]={title={{12,478631922},"어둠 붕괴"},description={"^fires a shadow missile at a target, dealing ([%+%-]?%d[%d,.%+%-to –]*) shadow damage to all enemies near the impact point and knocking them away%. after impact, leaves an energy field that lingers for ([%+%-]?%d[%d,.]* %a+), increasing magical damage dealt by ([%+%-]?%d[%d,.%+%-to –]*)%%, increasing casting speed by ([%+%-]?%d[%d,.%+%-to –]*)%%, reducing healing done by ([%+%-]?%d[%d,.%+%-to –]*)%%, and reducing mana costs by ([%+%-]?%d[%d,.%+%-to –]*)%%%.$","대상에게 어둠의 화살을 발사하여 충돌 지점 주변의 모든 적에게 \0311\031의 암흑 피해를 입히고 뒤로 밀쳐냅니다. 충격이 사라지면 \0312\031 동안 에너지장이 형성되어 마법 공격력이 \0313\031%만큼, 시전 속도가 \0314\031%만큼 증가하고, 치유 효과가 \0315\031%만큼, 주문에 소비되는 마나가 \0316\031%만큼 감소합니다.",{0,1,0,0,0,0},{1,2,3,4,5,6}},aura={"^magical damage dealt increased by ([%+%-]?%d[%d,.%+%-to –]*)%%%. casting speed increased by ([%+%-]?%d[%d,.%+%-to –]*)%%%. healing done reduced by ([%+%-]?%d[%d,.%+%-to –]*)%%%. spell and ability costs reduced by ([%+%-]?%d[%d,.%+%-to –]*)%%%.$","마법 공격력 \0311\031%만큼 증가\010시전 속도 \0312\031%만큼 증가\010치유 효과 \0313\031%만큼 감소\010주문 및 능력에 소비되는 비용 \0314\031%만큼 감소",{0,0,0,0},{1,2,3,4}}}
