rows[63480]={title={{8,744718106},"과부하"},description={"^focuses all the caster's energy into a single ball of lightning%. this ball grows for ([%+%-]?%d[%d,.]* %a+) until it finally explodes, dealing ([%+%-]?%d[%d,.%+%-to –]*) nature damage to all enemies within ([%+%-]?%d[%d,.%+%-to –]*) yards and knocking them down%.$","시전자의 에너지를 하나의 번개 구슬에 집중시킵니다. 구슬은 점점 커진 후 \0311\031 후 폭발하여 \0313\031미터 반경 내에 있는 모든 적에게 \0312\031의 자연 피해를 입히고 넘어뜨립니다.",{1,0,0},{1,2,3}},aura={{8,318235535},"기절함"}}
rows[63481]={title={{8,744718106},"과부하"},description={"^focuses all the caster's energy into a single ball of lightning%. this ball grows for ([%+%-]?%d[%d,.]* %a+) until it finally explodes, dealing ([%+%-]?%d[%d,.%+%-to –]*) nature damage to all enemies within ([%+%-]?%d[%d,.%+%-to –]*) yards and knocking them down%.$","시전자의 에너지를 하나의 번개 구슬에 집중시킵니다. 구슬은 점점 커진 후 \0311\031 후 폭발하여 \0313\031미터 반경 내에 있는 모든 적에게 \0312\031의 자연 피해를 입히고 넘어뜨립니다.",{1,0,0},{1,2,3}},aura={{33,1230850063},"기절 혹은 주문 방해받지 않음"}}
rows[63482]={title={{15,956850243},"번개 소용돌이"},description={"^spins around throwing off bolts of lightning at random enemy targets%. each bolt deals ([%+%-]?%d[%d,.%+%-to –]*) nature damage%.$","몸을 회전하며 번개 화살을 무작위 적 대상에게 날려 보냅니다. 각각의 화살은 \0311\031의 자연 피해를 입힙니다.",{0},{1}}}
rows[63483]={title={{15,956850243},"번개 소용돌이"},description={"^spins around throwing off bolts of lightning at random enemy targets%. each bolt deals ([%+%-]?%d[%d,.%+%-to –]*) nature damage%. lasts ([%+%-]?%d[%d,.]* %a+)%.$","몸을 회전하며 번개 화살을 무작위 적 대상에게 날려 보냅니다. 각각의 화살은 \0311\031의 자연 피해를 입힙니다. \0312\031 동안 지속됩니다.",{0,1},{1,2}},aura={"^emitting bolts of lightning at random enemy targets every ([%+%-]?%d[%d,.%+%-to –]*) sec%.$","\0311\031초마다 무작위 적 대상에게 화살 발사",{0},{1}}}
