rows[63485]={title={{18,1180923254},"번개 덩굴"},description={"^tendrils of lightning shoot out of the caster's chest, lifting them into the air%. these lightning tendrils deal ([%+%-]?%d[%d,.%+%-to –]*) nature damage to all enemies around the caster every second%.$","번개 덩굴이 시전자의 몸에서 뻗어나와 공중으로 솟아오릅니다. 주위의 모든 적에게 1초마다 \0311\031의 자연 피해를 입힙니다.",{0},{1}},aura={"^deals ([%+%-]?%d[%d,.%+%-to –]*) nature damage per second to nearby enemies%.$","1초마다 주위 적에게 \0311\031의 자연 피해",{0},{1}}}
rows[63486]={title={{18,1180923254},"번개 덩굴"},description={"^tendrils of lightning shoot out of the caster's chest, lifting them into the air%. these lightning tendrils deal ([%+%-]?%d[%d,.%+%-to –]*) nature damage to all enemies around the caster every second%.$","번개 덩굴이 시전자의 몸에서 뻗어나와 공중으로 솟아오릅니다. 주위의 모든 적에게 1초마다 \0311\031의 자연 피해를 입힙니다.",{0},{1}},aura={"^deals ([%+%-]?%d[%d,.%+%-to –]*) nature damage per second to nearby enemies%. cannot be stunned or interrupted%.$","1초마다 주위 적에게 \0311\031의 자연 피해\010기절 혹은 주문 방해받지 않음",{0},{1}}}
