rows[63489]={title={{15,419920152},"룬의 보호막"},description={"^covers the caster in magic runes, absorbing up to ([%+%-]?%d[%d,.%+%-to –]*) damage%. if ([%+%-]?%d[%d,.%+%-to –]*) damage is absorbed, this damage in converted into a powerful burst of energy, increasing the caster's damage by ([%+%-]?%d[%d,.%+%-to –]*)%% for ([%+%-]?%d[%d,.]* %a+)%.$","시전자를 마법의 룬으로 감싸 \0311\031의 피해를 흡수합니다. \0311\031의 피해가 흡수되면 피해는 강력한 에너지로 전환되어 \0314\031 동안 시전자의 공격력이 \0313\031%만큼 증가합니다.",{0,0,0,1},{1,1,3,4}},aura={"^absorbs ([%+%-]?%d[%d,.%+%-to –]*) damage%. increases damage done by ([%+%-]?%d[%d,.%+%-to –]*)%% when broken by damage%.$","\0311\031의 피해 흡수\010피해로 인해 파괴되면 공격력 \0312\031%만큼 증가",{0,0},{1,2}}}
rows[63490]={title={{13,2071130585},"죽음의 룬"},description={"^summons a rune of death at a random enemy target's location%. this rune deals ([%+%-]?%d[%d,.%+%-to –]*) shadow damage every half%-second to anyone within ([%+%-]?%d[%d,.%+%-to –]*) yards of that location%.$","무작위 적 대상의 위치에 죽음의 룬을 소환합니다. 룬 주위 \0312\031미터 반경 내에 있는 대상에게 0.5초마다 \0311\031의 암흑 피해를 입힙니다.",{0,0},{1,2}},aura={"^deals ([%+%-]?%d[%d,.%+%-to –]*) shadow damage every half%-second%.$","0.5초마다 \0311\031의 암흑 피해",{0},{1}}}
rows[63491]={title={{15,1223658058},"번개 작렬"},description={"^unleashes a large blast of lightning, dealing ([%+%-]?%d[%d,.%+%-to –]*) nature damage to all enemies within ([%+%-]?%d[%d,.%+%-to –]*) yards of the caster but killing the caster in the process%.$","거대한 번개를 방출하여 시전자를 희생하고 시전자로부터 \0312\031미터 반경 내에 있는 모든 적에게 \0311\031의 자연 피해를 입힙니다.",{0,0},{1,2}}}
