rows[63495]={title={{17,120545294},"전자기 붕괴"},description={"^deals ([%+%-]?%d[%d,.%+%-to –]*) nature damage to enemies in an area and increases nature damage taken by ([%+%-]?%d[%d,.%+%-to –]*)%% for ([%+%-]?%d[%d,.]* %a+)%. this spell favors targets at range%.$","주변 지역에 \0311\031의 자연 피해를 입히고 \0313\031 동안 받는 자연 피해를 \0312\031%만큼 증가시킵니다. 원거리에 있는 적을 우선적으로 공격합니다.",{0,0,1},{1,2,3}}}
