rows[63535]={title={{4,233522532},"잡아채기"},description={"^charges and grabs a random enemy target, tossing them into the caster's slag pot%. the target is unable to attack the caster and takes ([%+%-]?%d[%d,.%+%-to –]*) fire damage every second for ([%+%-]?%d[%d,.]* %a+)%. if the target survives, they are imbued with the magical slag, increasing their movement speed by ([%+%-]?%d[%d,.%+%-to –]*)%% and haste by ([%+%-]?%d[%d,.%+%-to –]*)%% for ([%+%-]?%d[%d,.]* %a+)%.$","무작위 적 대상에게 돌진하여 대상을 잡아 시전자의 용암재 단지에 집어넣습니다. 대상은 공격이 불가능한 상태가 되고 \0312\031 동안 1초마다 \0311\031의 화염 피해를 입습니다. 살아남은 대상은 용암재의 마력으로 \0315\031 동안 이동 속도가 \0313\031%만큼, 가속이 \0314\031%만큼 증가합니다.",{0,1,0,0,1},{1,2,3,4,5}}}
